306	// without any opening bracket or quote. "U.S.A." style initialisms are not
307	// listed: they usually do end a sentence when they come last, and guessing
308	// otherwise would trade one error for another.
309	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
310	
311	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
312	// only where whitespace or the end of the text follows. Requiring that keeps
313	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
314	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
315	
316	function endsWithAbbreviation(before) {
317	  const last = before.match(/(\S+)$/);
318	  if (last === null) {
319	    return false;
320	  }
321	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
322	  return ABBREVIATIONS.has(word);
323	}
324	
325	/**
326	 * Count the sentences in a piece of text.
327	 *
328	 * A sentence is a stretch of text containing at least one word and ending at a
329	 * terminator run, or at the end of the text. A lone period after a known
330	 * abbreviation does not end a sentence.
331	 *
332	 * @param {string} text
333	 * @returns {number}
334	 */
335	function sentenceCount(text) {
336	  assertText('sentenceCount', text);
337	  let count = 0;
338	  let start = 0;
339	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
340	    const before = text.slice(start, match.index);
341	    if (match[1] === '.' && endsWithAbbreviation(before)) {
342	      continue;
343	    }
344	    if (tokenize(before).length > 0) {
345	      count += 1;
346	    }
347	    start = match.index + match[0].length;
348	  }
349	  if (tokenize(text.slice(start)).length > 0) {
350	    count += 1;
351	  }
352	  return count;
353	}
