667	// A word is a run of letters or digits (any script), optionally joined to the
668	// next run by a single apostrophe (straight or typographic) or hyphen. The
669	// joiners are only part of a word when letters or digits sit on both sides, so
670	// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
671	// em dashes, periods and underscores, separates words.
672	const WORD_PATTERN = /[\p{L}\p{M}\p{N}]+(?:['’-][\p{L}\p{M}\p{N}]+)*/gu;
673	
674	function assertText(fn, value) {
675	  if (typeof value !== 'string') {
676	    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
677	  }
678	}
679	
680	// Private: the single definition of "word" shared by every statistic below.
681	function tokenize(text) {
682	  return text.match(WORD_PATTERN) ?? [];
683	}
684	
685	/**
686	 * Count the words in a piece of text.
687	 *
688	 * @param {string} text
689	 * @returns {number}
690	 */
691	function wordCount(text) {
692	  assertText('wordCount', text);
693	  return tokenize(text).length;
694	}
695	
696	// Words whose trailing period does not end a sentence. Compared lower-case and
697	// without any opening bracket or quote. "U.S.A." style initialisms are not
698	// listed: they usually do end a sentence when they come last, and guessing
699	// otherwise would trade one error for another.
700	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
701	
702	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
703	// only where whitespace or the end of the text follows. Requiring that keeps
704	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
705	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
706	
707	function endsWithAbbreviation(before) {
708	  const last = before.match(/(\S+)$/);
709	  if (last === null) {
710	    return false;
711	  }
712	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
713	  return ABBREVIATIONS.has(word);
714	}
715	
716	/**
717	 * Count the sentences in a piece of text.
718	 *
719	 * A sentence is a stretch of text containing at least one word and ending at a
720	 * terminator run, or at the end of the text. A lone period after a known
721	 * abbreviation does not end a sentence.
722	 *
723	 * @param {string} text
724	 * @returns {number}
725	 */
