727	  assertText('sentenceCount', text);
728	  let count = 0;
729	  let start = 0;
730	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
731	    const before = text.slice(start, match.index);
732	    if (match[1] === '.' && endsWithAbbreviation(before)) {
733	      continue;
734	    }
735	    if (tokenize(before).length > 0) {
736	      count += 1;
737	    }
738	    start = match.index + match[0].length;
739	  }
740	  if (tokenize(text.slice(start)).length > 0) {
741	    count += 1;
742	  }
