750	  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'had', 'has',
751	  'have', 'he', 'her', 'his', 'i', 'in', 'is', 'it', 'its', 'of', 'on', 'or',
752	  'she', 'that', 'the', 'their', 'there', 'they', 'this', 'to', 'was', 'were',
753	  'will', 'with',
754	]);
