776	      continue;
777	    }
778	    counts.set(word, (counts.get(word) ?? 0) + 1);
779	  }
780	  return [...counts]
781	    .map(([word, count]) => ({ word, count }))
782	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
783	    .slice(0, n);
784	}
